8	/**
9	 * Rejects a create request whose E.164 telephone is already used by an existing owner. Runs
10	 * after {@link NormalizeOwnerTelephone} has canonicalized the body's telephone, comparing it
11	 * against every stored owner's E.164 number so numbers that differ only in separators or an
12	 * assumed country code are still treated as duplicates.
13	 */
14	public class EnsureUniqueTelephone {
15	
16	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
17	            throws DuplicateTelephoneException {
18	        String telephone = request.getTelephone();
