3	import java.util.Locale;
4	import java.util.regex.Pattern;
5	
6	/**
7	 * Shared email handling: a syntactic validity check and canonicalization to lower case, so
8	 * equivalent addresses written with different letter cases are stored and returned in one
9	 * uniform form. Used to normalize an owner request's optional email before it is persisted.
10	 */
11	final class Emails {
12	
13	    private static final Pattern VALID = Pattern.compile(
14	            "^[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+(?:\\.[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+)*"
15	                    + "@[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?"
16	                    + "(?:\\.[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?)+$");
17	
18	    private Emails() {
19	    }
20	
21	    /** Whether {@code email} is a syntactically valid address. */
22	    static boolean isValid(String email) {
23	        return email != null && VALID.matcher(email).matches();
24	    }
25	
26	    /** Returns {@code email} lower-cased: its canonical stored form. */
27	    static String normalize(String email) {
28	        return email.toLowerCase(Locale.ROOT);
29	    }
30	}
