1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Locale;
7	
8	import org.springframework.samples.petclinic.model.Owner;
9	
10	/**
11	 * Shared household matching: canonicalizes the free-text fields that identify a household
12	 * (last name and address) so values that differ only in letter case, in the amount of
13	 * surrounding/internal whitespace, or (for the address) in common street-type
14	 * abbreviations compare equal. Used to detect when a new owner shares a household with an
15	 * existing one, and to derive the stable identifier that owners in the same household share.
16	 */
17	final class Households {
18	
19	    private Households() {
20	    }
21	
22	    /**
23	     * Canonicalizes a last name for case-insensitive, whitespace-insensitive comparison:
24	     * trims the ends, collapses every run of whitespace to a single space and lower-cases
25	     * the result. Returns an empty string when {@code lastName} is {@code null}.
26	     */
27	    private static String normalizeName(String lastName) {
28	        if (lastName == null) {
29	            return "";
30	        }
31	        return lastName.trim().replaceAll("\\s+", " ").toLowerCase();
32	    }
33	
34	    /**
35	     * Canonicalizes an address using the same normalization applied when an owner is created
36	     * (see {@link Addresses#normalize(String)}), so household comparisons see the stored,
37	     * abbreviation-expanded form. Returns an empty string when {@code address} is
38	     * {@code null}.
39	     */
40	    private static String normalizeAddress(String address) {
41	        String normalized = Addresses.normalize(address);
42	        return normalized == null ? "" : normalized;
43	    }
44	
45	    /**
46	     * Whether {@code owner} belongs to the household identified by {@code lastName} and
47	     * {@code address}, comparing the last name and the address in their canonical forms.
48	     */
49	    static boolean matches(Owner owner, String lastName, String address) {
50	        return normalizeName(lastName).equals(normalizeName(owner.getLastName()))
51	                && normalizeAddress(address).equals(normalizeAddress(owner.getAddress()));
52	    }
53	
54	    /**
55	     * The stable identifier shared by every owner in the household identified by
56	     * {@code lastName} and {@code address}. Derived purely from the canonical household key,
57	     * so the same household always yields the same id without any coordination.
58	     */
59	    static String id(String lastName, String address) {
60	        String key = normalizeName(lastName) + "\n" + normalizeAddress(address);
61	        return "H-" + sha256Hex(key).substring(0, 12).toUpperCase(Locale.ROOT);
62	    }
63	
64	    private static String sha256Hex(String value) {
65	        try {
66	            byte[] digest = MessageDigest.getInstance("SHA-256")
67	                    .digest(value.getBytes(StandardCharsets.UTF_8));
68	            StringBuilder hex = new StringBuilder(digest.length * 2);
69	            for (byte b : digest) {
70	                hex.append(String.format("%02x", b));
71	            }
72	            return hex.toString();
73	        }
74	        catch (NoSuchAlgorithmException e) {
75	            throw new IllegalStateException("SHA-256 not available", e);
76	        }
77	    }
78	}
