8	/**
9	 * When a create request opts into a shared household ({@code sharesHousehold} true) and an
10	 * existing owner already lives at the same address under the same last name, joins the new
11	 * owner to that household: every owner in it — the existing members and the new one — is
12	 * stamped with the same stable {@link Households#id(String, String) household id}. Owners
13	 * that are not part of a shared household keep a null id.
14	 */
15	public class AssignHousehold {
16	
17	    public void service(@Val Owner owner, @Val OwnerFieldsDto request,
18	            OwnerRepository ownerRepository) {
19	        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
20	            return;
21	        }
22	        String householdId = Households.id(request.getLastName(), request.getAddress());
23	        boolean joined = false;
24	        for (Owner existing : ownerRepository.findAll()) {
25	            if (Households.matches(existing, request.getLastName(), request.getAddress())) {
26	                existing.setHouseholdId(householdId);
27	                ownerRepository.save(existing);
28	                joined = true;
29	            }
30	        }
31	        if (joined) {
32	            owner.setHouseholdId(householdId);
33	        }
34	    }
35	}
